#!/usr/bin/env python3
import sys, os, re, math, gzip, zlib, base64, json, struct, glob
from collections import OrderedDict, defaultdict, Counter

try:
    from helps_data import HELP_BLOB
    _help_data = json.loads(zlib.decompress(base64.b85decode(HELP_BLOB.encode())).decode())
except Exception:
    _help_data = {"tools": [], "helps": {}, "main": "", "contact_stdout": "", "contact_stderr": ""}
TOOLS = _help_data.get("tools", [])
HELPS = _help_data.get("helps", {})
MAIN_HELP = _help_data.get("main", "")
VERSION = "9560abc"

def eprint(s=""):
    sys.stderr.write(str(s) + "\n")

def write_out(s):
    sys.stdout.write(s)

class BedError(Exception):
    pass

def die(msg, code=1):
    # msg already formatted (without trailing newline handling)
    sys.stderr.write(msg)
    if not msg.endswith("\n"):
        sys.stderr.write("\n")
    raise SystemExit(code)

def help_and_die(tool, msg=None, code=1):
    txt = HELPS.get(tool, "")
    out = txt
    if msg:
        out += "\n\n\n\n***** ERROR: " + msg + " *****\n"
    sys.stderr.write(out)
    raise SystemExit(code)

# ---------------- MT19937-64 ----------------
_MASK64 = (1 << 64) - 1
class MT64:
    N = 312; M = 156
    def __init__(self, seed):
        seed = int(seed) & _MASK64
        self.mt = [0]*self.N
        self.mt[0] = seed
        for i in range(1, self.N):
            prev = self.mt[i-1]
            self.mt[i] = (6364136223846793005 * (prev ^ (prev >> 62)) + i) & _MASK64
        self.idx = self.N
    def _twist(self):
        mt = self.mt
        for i in range(self.N):
            x = (mt[i] & 0xFFFFFFFF80000000) | (mt[(i+1) % self.N] & 0x7fffffff)
            xa = x >> 1
            if x & 1:
                xa ^= 0xB5026F5AA96619E9
            mt[i] = mt[(i + self.M) % self.N] ^ xa
        self.idx = 0
    def raw(self):
        if self.idx >= self.N:
            self._twist()
        y = self.mt[self.idx]; self.idx += 1
        y ^= (y >> 29) & 0x5555555555555555
        y ^= (y << 17) & 0x71D67FFFEDA60000
        y ^= (y << 37) & 0xFFF7EEE000000000
        y ^= (y >> 43)
        return y & _MASK64

def default_seed():
    # unseeded: use OS entropy / time-ish; not deterministic (as original)
    try:
        return int.from_bytes(os.urandom(8), 'little')
    except Exception:
        import time; return int(time.time())

# ---------------- number formatting ----------------
def fmt_num(x, prec=None):
    if isinstance(x, str):
        return x
    try:
        xf = float(x)
    except Exception:
        return str(x)
    if math.isnan(xf):
        return "nan"
    if math.isinf(xf):
        return "inf" if xf > 0 else "-inf"
    if prec is not None:
        s = format(xf, '.{}g'.format(int(prec)))
    else:
        s = format(xf, '.10g')
    # python gives e.g. 1e+08 - C++ also; keep
    return s

def fmt_fixed(x, digits):
    return format(float(x), '.{}f'.format(digits))

def is_int_str(s):
    if s is None: return False
    try:
        int(s); return True
    except Exception:
        return False

def is_num_str(s):
    if s is None: return False
    try:
        float(s); return True
    except Exception:
        return False

def parse_int(v, default=None):
    try: return int(float(v)) if isinstance(v,str) and ('.' in v) else int(v)
    except Exception: return default

# ---------------- records ----------------
class Record:
    __slots__ = ('fields','chrom','start','end','name','score','strand','fmt','blocks','bam')
    def __init__(self, fields, chrom, start, end, name='.', score='.', strand='.', fmt='bed', blocks=None, bam=None):
        self.fields = list(fields)
        self.chrom = chrom; self.start = int(start); self.end = int(end)
        self.name = name; self.score = score; self.strand = strand
        self.fmt = fmt; self.blocks = blocks; self.bam = bam
    def line(self):
        # regenerate coordinate fields based on fmt, keep other fields
        f = list(self.fields)
        try:
            if self.fmt == 'bed':
                if len(f) >= 3:
