# ---------------- option parsing ----------------
class Opts:
    def __init__(self):
        self.vals={}
        self.flags=set()
        self.multi={}
    def get(self,k,default=None):
        if k in self.vals: return self.vals[k]
        if k in self.multi: return self.multi[k]
        return default
    def has(self,k):
        return k in self.flags or k in self.vals or k in self.multi

def parse_opts(tool, argv, spec):
    """
    spec: dict name -> 'flag'|'value'|'multi'|'multi_or_value'
    aliases handled by caller mapping.
    Returns Opts, positionals
    If -h/--help present: print help stderr exit1 (original subcommand help behaviour)
    """
    if '-h' in argv or '--help' in argv:
        sys.stderr.write(HELPS.get(tool,""))
        raise SystemExit(1)
    opts=Opts()
    pos=[]
    i=0
    # for multi consumption state
    last_multi=None
    while i < len(argv):
        arg=argv[i]
        if arg=='--':
            pos.extend(argv[i+1:]); break
        # long options split with = ?
        if '=' in arg and arg.startswith('-'):
            k,v=arg.split('=',1)
            if k in spec:
                if spec[k]=='value':
                    opts.vals[k]=v; i+=1; continue
                elif spec[k] in ('multi',):
                    opts.multi.setdefault(k,[]).append(v); i+=1; continue
            # else fallthrough unknown
        if arg in spec:
            kind=spec[arg]
            if kind=='flag':
                opts.flags.add(arg); last_multi=None; i+=1; continue
            elif kind=='value':
                if i+1>=len(argv):
                    # error: help + specific
                    # determine msg like "-b option given, but no database file specified."
                    # generic caller will handle missing; we mimic intersect -b special later
                    opts.vals[arg]=None; i+=1; continue
                opts.vals[arg]=argv[i+1]; last_multi=None; i+=2; continue
            elif kind=='multi':
                # consume following non-option args (at least one if present)
                vals=[]
                j=i+1
                while j < len(argv) and (not argv[j].startswith('-') or argv[j]=='-' or argv[j] in ('stdin','/dev/stdin')):
                    # Note negative numbers start with -, but for multi file lists they are filenames
                    vals.append(argv[j]); j+=1
                # also if next is option or none, empty
                opts.multi.setdefault(arg,[]).extend(vals)
                last_multi=arg
                i=j; continue
            elif kind=='flag_or_value':
                # e.g. -s in sample could be flag or value; caller decides
                opts.flags.add(arg); i+=1; continue
        elif arg.startswith('-') and arg not in ('-','stdin'):
            # combined short flags? original doesn't support combining except maybe? Treat unknown
            help_and_die(tool, "Unrecognized parameter: {}".format(arg))
        else:
            # positional - could be continuation of multi? Our multi consumption already grabbed.
            pos.append(arg); i+=1; continue
    return opts, pos

def expand_file_list(vals):
    out=[]
    for v in vals or []:
        # wildcard handling: original note says -b may be followed with wildcard; shell usually expands.
        # If contains * ? and no file, glob it
        if any(ch in v for ch in '*?['):
            g=sorted(glob.glob(v))
            if g: out.extend(g)
            else: out.append(v)
        else:
            out.append(v)
    return out

