    __slots__ = ('fields','chrom','start','end','name','score','strand','fmt','blocks','bam')
    def __init__(self, fields, chrom, start, end, name='.', score='.', strand='.', fmt='bed', blocks=None, bam=None):
        self.fields = list(fields)
        self.chrom = chrom; self.start = int(start); self.end = int(end)
        self.name = name; self.score = score; self.strand = strand
        self.fmt = fmt; self.blocks = blocks; self.bam = bam
    def line(self):
        # regenerate coordinate fields based on fmt, keep other fields
        f = list(self.fields)
        try:
            if self.fmt == 'bed':
                if len(f) >= 3:
                    f[0]=self.chrom; f[1]=str(self.start); f[2]=str(self.end)
                if len(f) >= 4: f[3]=self.name if self.name is not None else f[3]
                # score/strand kept in fields unless changed externally
            elif self.fmt == 'gff':
                # ensure at least 9
                while len(f) < 9: f.append('.')
                f[0]=self.chrom; f[3]=str(self.start+1); f[4]=str(self.end)
                if len(f)>=7: f[6]=self.strand
                if len(f)>=6 and self.score is not None: 
                    pass
            elif self.fmt == 'vcf':
                while len(f) < 8: f.append('.')
                f[0]=self.chrom; f[1]=str(self.start+1)
            else:
                if len(f)>=3:
                    f[0]=self.chrom; f[1]=str(self.start); f[2]=str(self.end)
        except Exception:
            pass
        return "\t".join(f)
    def original(self):
        return "\t".join(self.fields)
    def clone_with(self, start=None, end=None, fields=None):
        r = Record(fields if fields is not None else list(self.fields), self.chrom,
                   self.start if start is None else start, self.end if end is None else end,
                   self.name, self.score, self.strand, self.fmt, self.blocks, self.bam)
        return r
    def length(self):
        return self.end - self.start
    def bed_fields(self):
        # canonical BED fields from fields if bed, else construct BED6-ish
        if self.fmt == 'bed':
            return list(self.fields)
        elif self.fmt == 'gff':
            # ??? conversion? Use name etc.
            return [self.chrom, str(self.start), str(self.end), self.name, str(self.score), self.strand]
        elif self.fmt == 'vcf':
            return [self.chrom, str(self.start), str(self.end), self.name, str(self.score), self.strand]
        return list(self.fields)

class FileData:
    def __init__(self, filename, records, headers, fmt, bam_header=None, bam_refs=None, raw_bam_records=None, is_bam=False, is_sam=False):
