def open_binary(filename):
    if filename is None or filename in ('stdin','-','/dev/stdin'):
        return sys.stdin.buffer.read()
    if not os.path.exists(filename):
        die("Error: Unable to open file {}. Exiting.\n".format(filename))
    with open(filename,'rb') as fh:
        return fh.read()

def read_text_lines(filename):
    """return (lines, raw_bytes) decompressing gzip if magic"""
    if filename is None or filename in ('stdin','-','/dev/stdin'):
        data = sys.stdin.buffer.read()
    else:
        if not os.path.exists(filename):
            die("Error: Unable to open file {}. Exiting.\n".format(filename))
        with open(filename,'rb') as fh:
            data = fh.read()
    if data[:2] == b'\x1f\x8b':
        try:
            data = gzip.decompress(data)
        except Exception:
            try:
                # multi-member
                import io
                out=b''; bio=io.BytesIO(data)
                while True:
                    try:
                        gz=gzip.GzipFile(fileobj=bio)
                        chunk=gz.read()
                        out+=chunk
                        rest=bio.read()
                        if not rest: break
                        bio=io.BytesIO(rest)
                    except Exception:
                        break
                data=out
            except Exception:
                pass
    # BAM detection handled by caller
    text = data.decode('utf-8', errors='replace')
    lines = text.splitlines()
    return lines, data

def is_header_line(line):
    return line.startswith('#') or line.startswith('track') or line.startswith('browser') or line.startswith('@HD') or line.startswith('@SQ') or line.startswith('@RG') or line.startswith('@PG') or line.startswith('@CO')

def determine_format(fields, headers, filename):
    # VCF header hint
    for h in headers:
        if h.startswith('##fileformat=VCF') or h.startswith('#CHROM'):
            return 'vcf'
    if not fields:
        return 'bed'
    # SAM-ish? flag etc - treat as unknown for bed parser
    # GFF: fields 4,5 ints (idx3,4), len>=8, field1 not int-start coord
    if len(fields) >= 8 and is_int_str(fields[3]) and is_int_str(fields[4]):
        # BED could also have int at 3? BED field4 is name (could be numeric), field5 score numeric... ambiguous.
        # GFF if field2 (idx1) is not an integer coordinate pair, or strand at idx6
        if not (is_int_str(fields[1]) and is_int_str(fields[2])):
            return 'gff'
        # BED9+ : fields 6 strand, fields 3 start? Actually BED thickStart int. GFF also...
        # If len>=9 and fields[6] in +- . and fields[2] is feature word? BED chrom start end name score strand thick...
        # Prefer BED when 1,2 are coords and 5 is strand-like at idx5
        if len(fields) >= 6 and fields[5] in ('+','-','.'):
            return 'bed'
        return 'gff'
    if len(fields) >= 3 and is_int_str(fields[1]) and is_int_str(fields[2]):
        return 'bed'
    if len(fields) >= 6 and is_int_str(fields[1]):
        # VCF: POS int, ID not int or REF allele-ish
        return 'vcf'
    if len(fields) >= 8 and is_int_str(fields[3]) and is_int_str(fields[4]):
        return 'gff'
    return None

def parse_bedpe_record(fields):
    # returns tuple or None
    return fields

def make_record(fields, fmt):
    if fmt == 'bed':
        chrom = fields[0]
        start = int(fields[1]); end = int(fields[2])
        name = fields[3] if len(fields)>3 else '.'
        score = fields[4] if len(fields)>4 else '.'
        strand = fields[5] if len(fields)>5 else '.'
        blocks=None
        if len(fields)>=12:
            try:
                bc=int(fields[9]); sizes=[int(x) for x in fields[10].rstrip(',').split(',') if x!='']
                starts=[int(x) for x in fields[11].rstrip(',').split(',') if x!='']
                blocks=(sizes, starts)
            except Exception:
                blocks=None
        return Record(fields, chrom, start, end, name, score, strand, 'bed', blocks)
    elif fmt == 'gff':
        chrom=fields[0]; start=int(fields[3])-1; end=int(fields[4])
        score=fields[5] if len(fields)>5 else '.'
        strand=fields[6] if len(fields)>6 else '.'
        # name from attributes ID= or Name= or field9
        name='.'
        if len(fields)>8:
            attrs=fields[8]
            m=re.search(r'(?:ID|Name)=([^;]+)', attrs)
            if m: name=m.group(1)
            else: name=attrs
        return Record(fields, chrom, start, end, name, score, strand, 'gff')
    elif fmt == 'vcf':
        chrom=fields[0]; pos=int(fields[1]); start=pos-1
        ref=fields[3] if len(fields)>3 else '.'
        reflen=len(ref) if ref and ref!='.' else 1
        end=start+max(reflen,1)
        name=fields[2] if len(fields)>2 else '.'
        score=fields[5] if len(fields)>5 else '.'
        strand='.'
        return Record(fields, chrom, start, end, name, score, strand, 'vcf')
    else:
        raise ValueError(fmt)

def load_records(filename, allow_bam=True):
    """Load BED/GFF/VCF, or BAM/SAM if magic/SAM. Returns FileData"""
    # read raw first to detect BAM/SAM
    if filename is None or filename in ('stdin','-','/dev/stdin'):
        data = sys.stdin.buffer.read()
        # need to be able to parse from bytes; stash? We'll parse directly below using data
        return _load_from_bytes(data, filename or 'stdin', allow_bam)
    else:
        if not os.path.exists(filename):
            die("Error: Unable to open file {}. Exiting.\n".format(filename))
        with open(filename,'rb') as fh:
            data = fh.read()
        return _load_from_bytes(data, filename, allow_bam)

# cache for stdin? stdin can only be read once; callers should pass filename once

def _load_from_bytes(data, filename, allow_bam=True):
    raw = data
    was_gzip=False
    if data[:2]==b'\x1f\x8b':
        was_gzip=True
        try:
            data=gzip.decompress(data)
        except Exception:
            # bgzf multi member
            import io
            out=b''; bio=io.BytesIO(data)
            while bio.tell() < len(data):
                try:
                    gz=gzip.GzipFile(fileobj=bio)
                    out+=gz.read()
                    pos=bio.tell()
                    # gzip module leaves? Use reading all concatenated via gzip.decompress alternative
                except Exception:
                    break
                break
            if out: data=out
    if allow_bam and data[:4]==b'BAM\x01':
        fd = parse_bam_bytes(data, filename)
        return fd
    # SAM detection: lines start @HD/@SQ and data lines have SAM format, for BAM tools caller handles; for generic, if filename endswith .sam or header present
    text = data.decode('utf-8', errors='replace')
    lines = text.splitlines()
    # SAM: if first lines @ and there are tab fields with flag ... detect
    is_sam=False
    if lines and (lines[0].startswith('@HD') or lines[0].startswith('@SQ')):
        # check a data line
        for ln in lines:
            if ln.startswith('@'): continue
            f=ln.split('\t')
            if len(f)>=11 and is_int_str(f[1]) and is_int_str(f[3]):
                is_sam=True
            break
    if is_sam:
        fd = parse_sam_text(text, filename)
        fd.is_sam=True
        return fd
    headers=[]
    records=[]
    fmt=None
    for rawline in lines:
        line=rawline.rstrip('\r')
        if line=='':
            continue
        if is_header_line(line) or line.startswith('##'):
            headers.append(line)
            continue
        # also #CHROM already header
        fields=line.split('\t')
        if fmt is None:
            fmt=determine_format(fields, headers, filename)
            if fmt is None:
                die("Error: unable to open file or unable to determine types for file {}\n\n- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n- Also ensure that your file has integer chromosome coordinates in the \n  expected columns (e.g., cols 2 and 3 for BED).\n".format(filename))
            # VCF header line #CHROM is header, already captured
        # validate coordinate fields
        try:
            rec=make_record(fields, fmt)
        except Exception:
            die("Error: unable to open file or unable to determine types for file {}\n\n- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n- Also ensure that your file has integer chromosome coordinates in the \n  expected columns (e.g., cols 2 and 3 for BED).\n".format(filename))
        # check end>=start? Original rejects start>end at first line; for later maybe also?
        if rec.end < rec.start:
            die("Error: unable to open file or unable to determine types for file {}\n\n- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n- Also ensure that your file has integer chromosome coordinates in the \n  expected columns (e.g., cols 2 and 3 for BED).\n".format(filename))
        records.append(rec)
    if fmt is None:
        fmt='bed'
    return FileData(filename, records, headers, fmt)

def load_genome(filename):
    if filename is None:
        return OrderedDict()
    lines,_ = read_text_lines(filename)
    genome=OrderedDict()
    for line in lines:
        if not line.strip(): continue
        if line.startswith('#'): continue
        parts=line.split('\t')
        if len(parts)<2:
            parts=line.split()
        if len(parts)>=2:
            try: genome[parts[0]]=int(parts[1])
            except Exception: pass
    return genome

