# ---------------- overlap helpers ----------------
def overlap_len(a_start,a_end,b_start,b_end):
    o=min(a_end,b_end)-max(a_start,b_start)
    return o if o>0 else 0

def overlaps(a,b):
    return a.chrom==b.chrom and overlap_len(a.start,a.end,b.start,b.end)>0

def build_index(records):
    idx=defaultdict(list)
    for r in records:
        idx[r.chrom].append(r)
    for c in idx:
        idx[c].sort(key=lambda x:(x.start,x.end))
    return idx

def find_overlaps(query, index, strand_mode=None, frac_a=0.0, frac_b=0.0, reciprocal=False, either=False, split=False):
    """return list of B records overlapping query satisfying filters. If split, query blocks considered."""
    cand = index.get(query.chrom, [])
    results=[]
    # determine query intervals
    q_intervals = get_intervals(query, split)
    for b in cand:
        if b.end <= min(q[0] for q in q_intervals) and False:
            pass
        b_intervals=get_intervals(b, split)
        total_overlap=0
        has=False
        for qs,qe in q_intervals:
            for bs,be in b_intervals:
                o=overlap_len(qs,qe,bs,be)
                if o>0:
                    has=True; total_overlap+=o
        if not has:
            continue
        if strand_mode=='s':
            if query.strand!=b.strand: continue
        elif strand_mode=='S':
            # opposite: only if both have strand and different? Original: requires different; '.' ?
            # check later; implement: if query.strand==b.strand: continue; also if either '.'? 
            if query.strand==b.strand: continue
        # fraction checks: use total_overlap ? For split, denominator
        qlen=query.length()
        blen=b.length()
        if split:
            qlen=sum(e-s for s,e in q_intervals)
            blen=sum(e-s for s,e in b_intervals)
        fa = (total_overlap/qlen) if qlen>0 else (1.0 if total_overlap>0 else 0)
        fb = (total_overlap/blen) if blen>0 else (1.0 if total_overlap>0 else 0)
        # default thresholds 1e-9 (overlap>0 ensures)
        need_a = frac_a if frac_a else 0.0
        need_b = frac_b if frac_b else 0.0
        # -r: if reciprocal, need_b mirrors need_a (when -F not set?) Caller handles
        ok_a = fa >= need_a if need_a>0 else True
        ok_b = fb >= need_b if need_b>0 else True
        if reciprocal:
            # both must satisfy frac_a (and frac_b if set)
            ok = ok_a and (fa>=need_a and fb>=need_a)  # approximate
            if need_b>0:
                ok = ok_a and ok_b and fb>=need_a and fa>=need_b
        elif either:
            ok = ok_a or ok_b
            # if only one fraction specified, or logic...
            if need_a==0 and need_b==0: ok=True
            elif need_a==0: ok=ok_b
            elif need_b==0: ok=ok_a
        else:
            ok = ok_a and ok_b
        if ok:
            results.append((b,total_overlap))
    return results

def get_intervals(rec, split=False):
    if split and rec.fmt=='bed' and rec.blocks:
        sizes,starts=rec.blocks
        ivs=[]
        for sz,st in zip(sizes,starts):
            ivs.append((rec.start+st, rec.start+st+sz))
        return ivs if ivs else [(rec.start,rec.end)]
    if split and rec.bam is not None:
        # use bam blocks
        blocks=rec.bam.get('blocks')
        if blocks: return blocks
    return [(rec.start, rec.end)]

def null_record_fields(b_fd, b_rec_template=None):
    # based on template record or first record of B
    if b_rec_template is not None:
        fmt=b_rec_template.fmt; n=len(b_rec_template.fields); template=b_rec_template
    elif b_fd is not None and b_fd.records:
        template=b_fd.records[0]; fmt=template.fmt; n=len(template.fields)
    elif b_fd is not None:
        fmt=b_fd.fmt; n=3; template=None
    else:
        return ['.','-1','-1']
    if fmt=='gff':
        return ['.','.','.','-1','-1','.','.','.','.'][:max(n,9)]
    if fmt=='vcf':
        out=['.']*n
        if n>1: out[1]='-1'
        return out
    # bed/bam bed
    out=[]
    for i in range(n):
        if i==0: out.append('.')
        elif i in (1,2): out.append('-1')
        elif i==4: out.append('-1')
        else: out.append('.')
    if n<3:
        out=['.','-1','-1']
    return out

