# ---------------- operations (map/merge/groupby) ----------------
VALID_OPS = ["sum","min","max","absmin","absmax","mean","median","mode","antimode","stdev","sstdev","collapse","distinct","distinct_sort_num","distinct_sort_num_desc","distinct_only","count","count_distinct","first","last","concat","freqdesc","freqasc"]

def warn_non_numeric(val, col):
    sys.stderr.write(" ***** WARNING: Non numeric value {} in {}.\n".format(val, col))

def apply_op(values, op, col_idx, delim=",", prec=None, warn=True):
    """values: list of strings. Returns string result. Empty values -> '.' except count -> '0'"""
    if op not in VALID_OPS:
        sys.stderr.write("\n*****\n***** ERROR: {} is not a valid operation. \n".format(op))
        return "."
    if op == "count":
        return str(len(values))
    if op == "count_distinct":
        return str(len(set(values)))
    if not values:
        return "." if op!="count" else "0"
    if op == "collapse":
        return delim.join(values)
    if op == "concat":
        return "".join(values)
    if op == "distinct":
        seen=[]; s=set()
        for v in values:
            if v not in s:
                s.add(v); seen.append(v)
        return delim.join(seen)
    if op == "distinct_sort_num":
        uniq=list(set(values))
        def keynum(x):
            try: return float(x)
            except Exception: return 0
        uniq.sort(key=keynum)
        return delim.join(uniq)
    if op == "distinct_sort_num_desc":
        uniq=list(set(values))
        def keynum(x):
            try: return float(x)
            except Exception: return 0
        uniq.sort(key=keynum, reverse=True)
        return delim.join(uniq)
    if op == "distinct_only":
        cnt=Counter(values)
        # sorted distinct keys (as observed)
        uniq_sorted=sorted(set(values))
        out=[]
        # Bug-compatible: delimiter is added for each sorted distinct element after the first
        # iterated element, even if that element was skipped.
        for idx, v in enumerate(uniq_sorted):
            if cnt[v]==1:
                if idx>0:
                    out.append(delim+v)
                else:
                    out.append(v)
        # The above yields leading delim when first sorted is non-unique but a later is unique,
        # and yields empty when none.
        # However when joining logic: if first unique not at idx0, string starts delim.
        return "".join(out) if out else ""
        # Note original returned '' (empty field) in that case
    if op == "first":
        return values[0]
    if op == "last":
        return values[-1]
    if op == "freqdesc" or op == "freqasc":
        cnt=Counter(values)
        items=list(cnt.items())
        if op=="freqdesc":
            items.sort(key=lambda kv: -kv[1])
        else:
            items.sort(key=lambda kv: kv[1])
        # stable order by first appearance for ties (Counter preserves insertion)
        return delim.join("{}:{}".format(k,v) for k,v in items)
    # numeric ops
    nums=[]
    for v in values:
        try:
            nums.append(float(v))
        except Exception:
