}
def missing_a_b(tool, opts, argv, a_key='-a', b_key='-b'):
    a = opts.get(a_key)
    b_vals = opts.get(b_key) if isinstance(opts.get(b_key), list) else ([opts.get(b_key)] if opts.get(b_key) else [])
    if a is None and not b_vals:
        help_and_die(tool, "No input file given. Exiting.")
