            help_and_die(tool, "{} option given, but no database file specified.".format(b_key))
        help_and_die(tool, "query and database files not specified.")
    return a, expand_file_list(b_vals)

def format_trimmed(rec):
    # for VCF, original line unchanged
    if rec.fmt=='vcf':
        return rec.original()
    return rec.line()

def do_intersect(argv, tool='intersect'):
    spec=dict(COMMON_AB_SPEC)
    spec.update({'-wa':'flag','-wb':'flag','-loj':'flag','-wo':'flag','-wao':'flag','-u':'flag','-c':'flag','-C':'flag','-v':'flag','-ubam':'flag'})
    opts, pos = parse_opts(tool, argv, spec)
    # positional continuation: if pos and -b already? parse_opts multi already consumed; pos treated as extra B files if -b present
    a_file = opts.get('-a') or opts.get('-abam')
    b_vals = opts.get('-b') or []
    if pos:
        # extra args are additional B files (as shell wildcard expansion looks like)
        b_vals = list(b_vals) + pos
        opts.multi['-b']=b_vals
    if a_file is None and not b_vals:
        help_and_die(tool, "No input file given. Exiting.")
    if a_file is not None and '-b' in argv and not b_vals:
        help_and_die(tool, "-b option given, but no database file specified.")
