    # BAM output mode
    if is_bam_a and not opts.has('-bed'):
        # write BAM filtered: records with any overlap retained once
        out_records=[]
        indexes=[OverlapIndex(bfd.records) for bfd in b_fds]
        for a in a_fd.records:
            hit=False
            for idx in indexes:
                if query_overlaps(a, idx, strand_mode, fa_thr, fb_thr, recip, either, split):
