    for m in ('-wa','-wb','-loj','-wo','-wao','-u','-c','-C','-v'):
        if opts.has(m): mode=m; break
    # Actually multiple modes could combine? e.g. -wa -wb both. Handle combos:
    wa=opts.has('-wa'); wb=opts.has('-wb'); loj=opts.has('-loj'); wo=opts.has('-wo'); wao=opts.has('-wao')
    u=opts.has('-u'); cflag=opts.has('-c'); Cflag=opts.has('-C'); vflag=opts.has('-v')
    out_lines=[]
    for a in a_fd_records:
