        if Cflag:
            for i,hits in enumerate(per_db):
                fid = file_id(i, b_fds[i]) if multi or names else None
                # When -C with single file, no name col? It printed just count. With names, include name even single?
                if names:
                    out_lines.append(a.original()+"\t"+str(names[i] if i<len(names) else str(i+1))+"\t"+str(len(hits)))
