def compute_genome_depth(genome, records, split=False, strand=None, five=False, three=False, scale=1.0):
    # returns dict chrom -> list of depth (float/int) or dict of runs
    # Use events per chrom
    depths={}
    for chrom,size in genome.items():
        events=[0]*(size+1)  # diff - may be huge for real genomes in tests (small genomes used likely). For hg19 size huge would be impossible - original also... tests use small.
        # But if size > 50M, this will be heavy; use interval runs method instead fallback
        depths[chrom]=events
    for r in records:
        if strand is not None and r.strand!=strand: continue
        if r.chrom not in depths: continue
        size=genome[r.chrom]
        ivs=get_intervals(r,split) if split else [(r.start,r.end)]
        if five:
            if r.strand=='-':
                pos=r.end-1; ivs=[(pos,pos+1)]
            else:
                ivs=[(r.start,r.start+1)]
        elif three:
            if r.strand=='-':
                ivs=[(r.start,r.start+1)]
            else:
                pos=r.end-1; ivs=[(pos,pos+1)]
        for s,e in ivs:
            s=max(0,s); e=min(size,e)
            if e<=s: continue
            diff=depths[r.chrom]
            diff[s]+=1; 
            if e < len(diff): diff[e]-=1
    # convert diff to depth runs/hist
    result={}
    for chrom, diff in depths.items():
        depth=[]
        cur=0
        for i in range(genome[chrom]):
            cur+=diff[i]
            depth.append(cur)
        result[chrom]=depth
    return result

