def load_fasta(filename, full_header=False):
    lines,_=read_text_lines(filename) if filename not in ('stdin','-','/dev/stdin') else (sys.stdin.read().splitlines(),None)
    seqs=OrderedDict()  # name -> (full header, seq string, raw lines list (header, seq lines))
    raw_records=[] # list of dict
    cur=None
    for line in lines:
        if line.startswith('>'):
            header=line[1:]
            name=header if full_header else (re.split(r'[ \t]', header)[0])
            cur={'header':header,'name':name,'seq_parts':[],'lines':[]}
            raw_records.append(cur)
            seqs[name]=cur
        else:
            if cur is not None:
                cur['seq_parts'].append(line.strip())
                cur['lines'].append(line)
    for rec in raw_records:
        rec['seq']="".join(rec['seq_parts'])
    return seqs, raw_records

def revcomp(seq, rna=False):
    if rna:
        comp=str.maketrans('ACGUacguNn','UGCAugcaNn')
        # RNA complement: A->U, C->G, G->C, U->A
        # Build mapping manually
        m={}
        pairs={'A':'U','C':'G','G':'C','U':'A','a':'u','c':'g','g':'c','u':'a','N':'N','n':'n'}
        return "".join(pairs.get(ch,ch) for ch in reversed(seq))
    else:
        pairs={'A':'T','C':'G','G':'C','T':'A','a':'t','c':'g','g':'c','t':'a','N':'N','n':'n','U':'A','u':'a'}
        return "".join(pairs.get(ch,ch) for ch in reversed(seq))

def get_seq_for_record(seqs, r, split=False, strand_force=False, rna=False):
    entry=seqs.get(r.chrom)
    if entry is None:
        # warning? Original maybe Error: chromosome not found ... We'll output empty and warn to stderr
        sys.stderr.write("Error: chromosome {} not found in FASTA.\n".format(r.chrom))
        return ""
    seq=entry['seq']
    if split and r.blocks:
        parts=[]
        for sz,st in zip(r.blocks[0], r.blocks[1]):
            s=r.start+st; e=s+sz
            parts.append(seq[s:e])
        extracted="".join(parts)
    else:
        extracted=seq[r.start:r.end]
    if strand_force and r.strand=='-':
        extracted=revcomp(extracted, rna=rna)
    return extracted

