            # Simple skip+warn this record:
            sys.stderr.write("*****WARNING: Query {} is marked as paired, but its mate does not occur next to it in your BAM file.  Skipping. \n".format(b['name']))
            idx+=1
    content1="".join(entries1); content2="".join(entries2)
    # Write files (could be same /dev/stdout interleaving - write 1 then 2)
    if fq_path=='/dev/stdout': write_out(content1)
    else:
        with open(fq_path,'w') as fh: fh.write(content1)
    if fq2_path=='/dev/stdout': write_out(content2)
    else:
        with open(fq2_path,'w') as fh: fh.write(content2)

