                cchrom,cs,ce,cstrand=cur
                if rs-ce <= d:
                    cur=(cchrom,cs,max(ce,re),cstrand); cur_records_local.append(r)
                else:
                    flush_local(cur,cur_records_local); cur=(r.chrom,rs,re); cur_records_local=[r]
            flush_local(cur,cur_records_local)
        # output order: chrom by first appearance in original records, then start, then strand (+ before -?) - use start primary after chrom appearance
        chrom_app={}
        for i,r in enumerate(records):
            if r.chrom not in chrom_app: chrom_app[r.chrom]=i
        merged.sort(key=lambda x: (chrom_app.get(x[0],0), x[1], x[2]))
        out=[ "\\t".join(parts) for cchrom,cs,ce,parts in merged]
        if out: write_out("\\n".join(out)+"\\n")
        return
    # grouping: iterate records in given order, merging when chrom same, strand condition, distance
    cur=None; cur_records=[]
    def flush():
        if cur is None: return
        chrom,s,e,strand = cur
        if cur_records and all(r.end==r.start for r in cur_records):
